     1	package br.com.loja.pedidos.shipping;
     2	
     3	import br.com.loja.pedidos.common.ApiException;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	
     7	/** Delivery priced and timed by an external carrier; the dispatch delay of the region is added on top. */
     8	public class CarrierShippingOption implements ShippingOption {
     9	
    10	    private final String code;
    11	    private final ServiceLevel level;
    12	    private final CarrierGateway carrier;
    13	
    14	    public CarrierShippingOption(String code, ServiceLevel level, CarrierGateway carrier) {
    15	        this.code = code;
    16	        this.level = level;
    17	        this.carrier = carrier;
    18	    }
    19	
    20	    @Override
    21	    public String code() {
    22	        return code;
    23	    }
    24	
    25	    @Override
    26	    public ShippingQuote quote(ShippingRequest request) {
    27	        long grams = request.weightKg().multiply(BigDecimal.valueOf(1000)).setScale(0, RoundingMode.CEILING)
    28	                .longValueExact();
    29	        return switch (carrier.quote(request.zipCode(), grams, level)) {
    30	            case CarrierGateway.Quoted q -> new ShippingQuote(q.price(),
    31	                    (int) ((q.etaHours() + 23) / 24) + request.region().dispatchDelayDays());
    32	            case CarrierGateway.NotServed n -> throw ApiException.unprocessable("SHIPPING_METHOD_UNAVAILABLE");
    33	            case CarrierGateway.Unavailable u -> throw new ApiException("CARRIER_UNAVAILABLE", 503);
    34	        };
    35	    }
    36	}
